import numpy as np

def softmax(z):
    z = z - z.max(axis=1, keepdims=True)
    e = np.exp(z)
    return e / e.sum(axis=1, keepdims=True)

def make_obs(agent=None, ball=None, reward=None, prev_mode='zero'):
    x = np.zeros((10, 10, 5), dtype=float)
    # wall border in channel 3
    x[0, :, 3] = 1
    x[9, :, 3] = 1
    x[:, 0, 3] = 1
    x[:, 9, 3] = 1
    if agent is not None:
        x[agent[0], agent[1], 0] = 1
    if ball is not None:
        x[ball[0], ball[1], 1] = 1
    if reward is not None:
        x[reward[0], reward[1], 2] = 1
    if prev_mode == 'agent' and agent is not None:
        x[agent[0], agent[1], 4] = 1
    elif prev_mode == 'ball' and ball is not None:
        x[ball[0], ball[1], 4] = 1
    return x.reshape(-1)

positions = [(1,1), (1,5), (1,8),
             (5,1), (5,5), (5,8),
             (8,1), (8,5), (8,8)]

labels = []
X = []
for prev in ['zero', 'agent']:
    for pos in positions:
        labels.append(f"prev={prev:5s} agent={pos}")
