import numpy as np

def make_state(agent, objects, prev='zero'):
    x = np.zeros(500)
    for r in range(10):
        for c in range(10):
            if r in (0,9) or c in (0,9):
                x[(r*10+c)*5+3] = 1          # wall border = obstacle
    ar, ac = agent
    x[(ar*10+ac)*5+0] = 1                # agent
    for (r,c,ch) in objects:
        x[(r*10+c)*5+ch] = 1
    if prev == 'agent':
        x[(ar*10+ac)*5+4] = 1
    return x

agent = (5,5)
neigh = {'up':(4,5),'down':(6,5),'left':(5,4),'right':(5,6),
         'upleft':(4,4),'upright':(4,6),'downleft':(6,4),'downright':(6,6)}

states, labels = [], []
states.append(make_state(agent, [])); labels.append('baseline')
for ch, nm in [(1,'ball'),(2,'reward'),(3,'obst')]:
    for name,pos in neigh.items():
        states.append(make_state(agent, [(pos[0],pos[1],ch)]))
        labels.append(f'{nm} {name}')

X = np.array(states)
out = forward(X)
p = np.exp(out - out.max(axis=1, keepdims=True))
p = p / p.sum(axis=1, keepdims=True)
print('label        | p_up  p_down p_left p_right | argmax')
for lab, pr in zip(labels, p):
    print(f'{lab:12s} | {pr[1]:.3f} {pr[2]:.3f} {pr[3]:.3f} {pr[4]:.3f} | {int(np.argmax(pr))}')
